// ── 학교급 고르기 칩 (교과별 토론·논제 목록이 함께 쓴다) ──────────────
function levelChipsHTML() {
    const cur = getSchoolLevel();
    return `<div class="level-pref" role="group" aria-label="우리 학교급">
        <span class="level-pref-label"><i class="fa-solid fa-school"></i> 우리 학교급</span>
        ${SCHOOL_LEVELS.map(l => `<button type="button" class="level-chip ${cur === l.key ? "active" : ""}" data-level-pref="${l.key}" aria-pressed="${cur === l.key}">${l.label}</button>`).join("")}
    </div>`;
}
function bindLevelChips(root, onChange) {
    root.querySelectorAll("[data-level-pref]").forEach(b => b.addEventListener("click", () => {
        setSchoolLevel(b.dataset.levelPref);
        onChange();
        if (typeof window.__topicLevelChanged === "function") window.__topicLevelChanged();
    }));
}

// ── 교과별 토론 ───────────────────────────────────────────────────
function subjectTopics(sub, lv) {
    const mine = (t) => !!t.subject && [].concat(t.subject).includes(sub.key);
    const base = sub.math
        ? debateTopicsDB.filter(t => t.type === "fact" && TOPIC_STATS[t.claim])
        : debateTopicsDB.filter(t => (sub.fields || []).includes(t.field));
    const order = { "고등": 0, "중학·고등": 1, "초등·중학": 2 };
    const rest = base.filter(t => !mine(t) && topicFitsLevel(t, lv));
    if (lv === "고등") rest.sort((a, b) => order[a.level] - order[b.level]);
    return { own: debateTopicsDB.filter(t => mine(t) && topicFitsLevel(t, lv)), rest };
}

// 이 교과의 2022 개정 교육과정 과목을 모두 보여 주고, 성취기준마다 이은 논제를 붙인다
const CUR_TYPES = ["공통", "일반 선택", "진로 선택", "융합 선택", "계열 선택"];
const CUR_TYPE_LABEL = { "공통": "공통 과목", "일반 선택": "일반 선택", "진로 선택": "진로 선택", "융합 선택": "융합 선택", "계열 선택": "계열 선택 · 과학·체육·예술 계열 고등학교" };
function curTopicsByCode(sub) {
    const map = {};
    debateTopicsDB.forEach(t => (t.std || []).forEach(c => {
        const co = curCourse(c);
        if (!co || co[1] !== sub.key || !CURRICULUM[c]) return;
        (map[c] = map[c] || []).push(t);
    }));
    return map;
}
function curTopicBtns(list) {
    return list.map(t => `<button type="button" class="cur-topic" onclick="openTopicWorksheet(${debateTopicsDB.indexOf(t)})" title="이 논제로 학습지 만들기"><span class="topic-chip topic-chip-${t.type}">${(TOPIC_TYPE_INFO[t.type] || {}).label || ""}</span><span>${t.claim}</span></button>`).join("");
}
function subjectCurriculumHTML(sub, lv) {
    const courses = Object.keys(CURRICULUM_COURSES).filter(ab => CURRICULUM_COURSES[ab][1] === sub.key);
    if (!courses.length) return "";
    const head = `<h4 class="subject-sub"><i class="fa-solid fa-book-bookmark"></i> 교육과정에서 찾은 토론 거리`;
    if (lv === "초등" || lv === "중학") return `${head}</h4><p class="cur-note">2022 개정 <strong>고등학교</strong> 교육과정의 과목과 성취기준입니다. 위 학교급을 '고등'이나 '전체'로 바꾸면 보입니다.</p>`;
    const byCode = curTopicsByCode(sub);
    const codesOf = (ab) => Object.keys(byCode).filter(c => curAbbr(c) === ab).sort();
    const topicN = new Set(Object.values(byCode).flat()).size;
    const courseHTML = (ab) => {
        const [name, , , n] = CURRICULUM_COURSES[ab];
        const codes = codesOf(ab);
        const tn = new Set(codes.flatMap(c => byCode[c])).size;
        return `
                <details class="cur-course">
                    <summary><strong>${name}</strong>${tn ? `<span class="cur-badge">논제 ${tn}</span>` : ""}<span class="cur-count">성취기준 ${n}</span></summary>
                    <ul class="cur-stds">${codes.map(c => `
                        <li class="cur-std">
                            <p class="cur-std-text"><code>[${c}]</code> ${CURRICULUM[c]}</p>
                            <div class="cur-std-topics">${curTopicBtns(byCode[c])}</div>
                        </li>`).join("")}
                    </ul>
                    <button type="button" class="cur-all-btn" data-ab="${ab}" data-n="${n}"><i class="fa-solid fa-list-ul"></i> 이 과목 성취기준 ${n}개 모두 보기</button>
                    <ul class="cur-all" hidden></ul>
                </details>`;
    };
    const groups = CUR_TYPES.map(ty => {
        const list = courses.filter(ab => CURRICULUM_COURSES[ab][2] === ty);
        return list.length ? `<p class="cur-type-head">${CUR_TYPE_LABEL[ty]} <small>${list.length}과목</small></p><div class="cur-courses">${list.map(courseHTML).join("")}</div>` : "";
    }).join("");
    return `${head} <small>과목 ${courses.length}개 · 논제 ${topicN}개</small></h4>
            <p class="cur-note">2022 개정 고등학교 교육과정(교육부 고시 제2022-33호)에서 이 교과의 과목을 모두 모았습니다. 과목을 펼치면 논제와 이은 성취기준이 나오고, '모두 보기'를 누르면 그 과목의 성취기준 전체를 볼 수 있습니다. 수업 계획이나 세특에 성취기준 코드를 그대로 쓰면 됩니다.</p>
            ${groups}`;
}
// 과목별 성취기준 전문은 curriculum.json에 따로 두고, 누를 때 한 번만 불러온다
let CUR_ALL = null;
function loadCurriculumAll() {
    if (CUR_ALL) return Promise.resolve(CUR_ALL);
    return fetch(`curriculum.json?v=${ASSET_VERSION}`)
        .then(r => { if (!r.ok) throw new Error(r.status); return r.json(); })
        .then(d => { CUR_ALL = {}; d.courses.forEach(c => { CUR_ALL[c.ab] = c.std; }); return CUR_ALL; });
}
function bindCurriculumAll(root, sub) {
    const byCode = curTopicsByCode(sub);
    root.querySelectorAll(".cur-all-btn").forEach(btn => btn.addEventListener("click", () => {
        const list = btn.nextElementSibling;
        const linked = btn.previousElementSibling;
        const label = `<i class="fa-solid fa-list-ul"></i> 이 과목 성취기준 ${btn.dataset.n}개 모두 보기`;
        if (!list.hidden) { list.hidden = true; linked.hidden = false; btn.innerHTML = label; return; }
        btn.disabled = true;
        btn.textContent = "불러오는 중…";
        loadCurriculumAll().then(all => {
            list.innerHTML = (all[btn.dataset.ab] || []).map(([code, text]) => `
                <li class="${byCode[code] ? "linked" : ""}"><p class="cur-std-text"><code>[${code}]</code> ${text}</p>${byCode[code] ? `<div class="cur-std-topics">${curTopicBtns(byCode[code])}</div>` : ""}</li>`).join("");
            list.hidden = false;
            linked.hidden = true;
            btn.innerHTML = `<i class="fa-solid fa-chevron-up"></i> 논제와 이은 성취기준만 보기`;
        }).catch(() => {
            list.innerHTML = `<li>성취기준 목록을 불러오지 못했습니다. 인터넷 연결을 확인한 뒤 다시 눌러 주세요.</li>`;
            list.hidden = false;
            btn.innerHTML = label;
        }).finally(() => { btn.disabled = false; });
    }));
}

let subjectKey = null;
function renderSubjectSection() {
    const box = document.getElementById("subject-panel");
    if (!box || typeof SUBJECT_GUIDE === "undefined") return;
    if (!subjectKey) {
        let saved = null;
        try { saved = localStorage.getItem("pbc-subject"); } catch (e) {}
        if (saved === "history" || saved === "ethics") saved = "social";
        subjectKey = (SUBJECT_GUIDE.find(s => s.key === saved) || SUBJECT_GUIDE[0]).key;
    }
    const sub = SUBJECT_GUIDE.find(s => s.key === subjectKey) || SUBJECT_GUIDE[0];
    const lv = getSchoolLevel();
    const tp = subjectTopics(sub, lv);
    const restShown = tp.rest.slice(0, tp.own.length ? 4 : 8);
    const shownN = tp.own.length + restShown.length;
    const totalN = tp.own.length + tp.rest.length;
    const scenes = sub.scenes || (sub.scene ? [sub.scene] : []);

    const techCards = sub.techs.map(x => {
        const t = techniques.find(tt => tt.id === x.id);
        if (!t) return "";
        return `<button type="button" class="subject-tech" onclick="openModal('tech','${t.id}')">
                <span class="subject-tech-icon"><i class="fa-solid ${t.icon}"></i></span>
                <span class="subject-tech-body"><strong>${t.name}</strong><span>${x.why}</span></span>
            </button>`;
    }).join("");

    const sceneCards = scenes.map(sc => `
            <div class="subject-scene">
                <span class="subject-scene-tag"><i class="fa-regular fa-clock"></i> ${sc.min}분</span>
                <h5>${sc.unit}<small> · ${sc.tech}</small></h5>
                <p>${sc.flow}</p>
            </div>`).join("");

    const topicRow = (t) => {
        const idx = debateTopicsDB.indexOf(t);
        const meta = TOPIC_TYPE_INFO[t.type] || {};
        return `<li class="subject-topic">
                <span class="topic-chip topic-chip-${t.type}">${meta.label || ""}</span>
                <span class="subject-topic-claim">${t.claim}${t.now ? `<small class="subject-topic-now"><b>지금은</b> ${t.now}</small>` : ""}</span>
                ${t.unit ? `<span class="subject-topic-unit">${t.unit}</span>` : `<span class="subject-topic-level">${t.level}</span>`}
                <select class="subject-topic-techsel" aria-label="토론 기법으로 학습지 만들기" onchange="if (this.value) { openTopicWorksheet(${idx}, this.value); this.value = ''; }">
                    <option value="">기법으로 학습지 ▾</option>
                    <optgroup label="이 교과에 잘 맞는 기법">${sub.techs.map(x => techniques.find(tt => tt.id === x.id)).filter(Boolean).map(tt => `<option value="tech-${tt.id}">${techShortName(tt)}</option>`).join("")}</optgroup>
                    <optgroup label="다른 기법">${techniques.filter(tt => !sub.techs.some(x => x.id === tt.id)).map(tt => `<option value="tech-${tt.id}">${techShortName(tt)}</option>`).join("")}</optgroup>
                </select>
                <button type="button" class="subject-topic-ws" onclick="openTopicWorksheet(${idx})"><i class="fa-solid fa-file-pen"></i> 학습지</button>
            </li>`;
    };
    // 과목 갈래(groups)가 있는 교과는 단원 앞머리로 논제를 묶어 보여 준다
    let ownRows = tp.own.map(topicRow).join("");
    if (sub.groups) {
        const head = (t) => String(t.unit || "").split(" · ")[0];
        const used = new Set();
        ownRows = sub.groups.map(g => {
            const list = tp.own.filter(t => !used.has(t) && g.units.includes(head(t)));
            list.forEach(t => used.add(t));
            return list.length ? `<li class="subject-topic-group">${g.label}</li>` + list.map(topicRow).join("") : "";
        }).join("");
        const others = tp.own.filter(t => !used.has(t));
        if (others.length) ownRows += `<li class="subject-topic-group">${sub.groupRest || "그 밖의 논제"}</li>` + others.map(topicRow).join("");
    }
    const topicRows = ownRows +
        (restShown.length ? (tp.own.length ? `<li class="subject-topic-divider">다른 분야에서 함께 쓸 만한 논제</li>` : "") + restShown.map(topicRow).join("") : "");

    const srcLinks = (sub.sources || []).map(k => STAT_SOURCES[k]).filter(Boolean)
        .map(s => `<a class="subject-src" href="${s.url}" target="_blank" rel="noopener"><i class="fa-solid fa-arrow-up-right-from-square"></i> ${s.name}</a>`).join("");

    box.innerHTML = `
        ${levelChipsHTML()}
        <div class="subject-tabs" role="tablist" aria-label="교과 고르기">
            ${SUBJECT_GUIDE.map(s => `<button type="button" role="tab" class="subject-tab ${s.key === sub.key ? "active" : ""}" data-subject="${s.key}" aria-selected="${s.key === sub.key}"><i class="fa-solid ${s.icon}"></i> ${s.label}</button>`).join("")}
        </div>
        <article class="subject-card">
            <div class="subject-head">
                <h3><i class="fa-solid ${sub.icon}"></i> ${sub.label} 수업에서 토론하기</h3>
                <p>${sub.hook}</p>
            </div>

            <h4 class="subject-sub"><i class="fa-regular fa-clock"></i> 이렇게 짧게 넣어 보세요</h4>
            <div class="subject-scenes">${sceneCards}</div>

            ${sub.frames ? `
            <div class="subject-frames">
                <h4 class="subject-sub"><i class="fa-regular fa-comment-dots"></i> ${sub.frames.title}</h4>
                <ul>${sub.frames.items.map(f => `<li>${f}</li>`).join("")}</ul>
                <p class="subject-frames-note">칠판에 붙이거나 학생 책상 위에 올려 두면, 말문이 막힐 때 바로 꺼내 씁니다.</p>
            </div>` : ""}

            <h4 class="subject-sub"><i class="fa-solid fa-comments"></i> 이 교과에 잘 맞는 기법</h4>
            <div class="subject-techs">${techCards}</div>

            ${(sub.tips || []).length ? `<ul class="subject-tips">${sub.tips.map(t => `<li><i class="fa-solid fa-lightbulb"></i> ${t}</li>`).join("")}</ul>` : ""}

            <h4 class="subject-sub"><i class="fa-solid fa-scale-balanced"></i> 이 교과의 논제 <small>${totalN}개 가운데 ${shownN}개 · 누르면 학습지가 만들어집니다</small></h4>
            <ul class="subject-topics">${topicRows || `<li class="subject-empty">이 학교급에 맞는 논제가 없습니다. 학교급을 '전체'로 바꿔 보세요.</li>`}</ul>

            ${subjectCurriculumHTML(sub, lv)}

            ${srcLinks ? `<h4 class="subject-sub"><i class="fa-solid fa-chart-column"></i> 근거 자료 찾기</h4><div class="subject-srcs">${srcLinks}</div>` : ""}
            ${sub.literature ? `<button type="button" class="btn btn-secondary subject-lit-btn" onclick="openLiteraturePanel()"><i class="fa-solid fa-feather"></i> 교과서 문학 ${literatureWorks.length}편에서 논제 찾기</button>` : ""}
        </article>`;

    box.querySelectorAll("[data-subject]").forEach(b => b.addEventListener("click", () => {
        subjectKey = b.dataset.subject;
        try { localStorage.setItem("pbc-subject", subjectKey); } catch (e) {}
        renderSubjectSection();
    }));
    bindLevelChips(box, renderSubjectSection);
    bindCurriculumAll(box, sub);
}

window.openLiteraturePanel = function () {
    const link = document.querySelector('.nav-links a[href="#topic-section"]');
    if (link) link.click();
    const tab = document.querySelector('.topic-tab-btn[data-topic-tab="lit"]');
    if (tab) tab.click();
};

// 토론 기법 목록으로 건너가기 (연수 화면에서 쓴다)
window.openQuickTechniques = function () {
    const link = document.querySelector('.nav-links a[href="#techniques-section"]');
    if (link) link.click();
    const btn = document.querySelector('.tech-filter-btn[data-filter="all"]');
    if (btn) btn.click();
};

// ── 기법 설명 창에 붙는 '짧게 쓰는 법 · 관찰과 기록' ──────────────────
function techClassGuideHTML(techId) {
    const g = (typeof TECH_CLASS_GUIDE !== "undefined") && TECH_CLASS_GUIDE[techId];
    if (!g) return "";
    return `
        <div class="modal-section tech-quick">
            <h4><i class="fa-solid fa-feather-pointed"></i> 짧게 쓰는 법</h4>
            <p class="tech-quick-slots">한 차시 안에서 넣기 좋은 자리 · ${g.quick.slots.map(s => `<span>${s}</span>`).join("")}</p>
            <p>${g.quick.how}</p>
        </div>
        <div class="modal-section tech-assess">
            <h4><i class="fa-solid fa-clipboard-check"></i> 관찰과 평가</h4>
            <p class="tech-assess-lead">활동 중에 이런 모습을 눈여겨보세요.</p>
            <ul class="tech-observe">${g.observe.map(o => `<li>${o}</li>`).join("")}</ul>
            <div class="tech-rubric-wrap">
                <table class="tech-rubric">
                    <thead><tr><th>기준</th><th>잘함</th><th>보통</th><th>노력 필요</th></tr></thead>
                    <tbody>${g.rubric.map(r => `<tr><th>${r.k}</th><td data-label="잘함">${r.hi}</td><td data-label="보통">${r.mid}</td><td data-label="노력 필요">${r.lo}</td></tr>`).join("")}</tbody>
                </table>
            </div>
        </div>
        <div class="modal-section tech-setuk">
            <h4><i class="fa-solid fa-pen-nib"></i> 교과세특 문장 예시</h4>
            ${g.setuk.map(s => `<blockquote>${s}</blockquote>`).join("")}
            <p class="tech-setuk-note"><i class="fa-solid fa-circle-info"></i> 예시 문장을 그대로 옮기면 모든 학생의 기록이 같아집니다. 학생이 실제로 한 말과 행동, 다룬 논제로 바꿔 쓰세요.</p>
        </div>`;
}

// ── 연수 안내 ─────────────────────────────────────────────────────
// 제목·시간은 여기서 고치면 화면과 인쇄물에 함께 반영된다.
const TRAINING = {
    title: "함께 만드는 수업 속 토론",
    tagline: "가볍게 시작해 깊이 남는 — 교과를 넘어 함께 짓는 토론 수업",
    subtitle: "고등학교 전교사 연수 · 100분(1시간 40분)",
    url: "https://woorimalsam-lab.github.io/Picture-BC/#subject-section",
    flow: [
        { min: 15, title: "토론이란 무엇인가 · 토론의 개념", desc: "토론은 이기고 지는 말싸움이 아니라, 근거를 들어 생각을 나누며 더 나은 판단에 이르는 과정입니다. 사실·가치·정책 논제의 차이와, 경쟁 토론과 비경쟁 토론의 차이를 짧게 살핍니다.", links: [{ label: "토론 이론", go: "#theory-section", icon: "fa-graduation-cap" }, { label: "토론 논제", go: "#topic-section", icon: "fa-scale-balanced" }] },
        { min: 15, title: "가치수직선 토론 체험", desc: "선생님들이 학생이 되어 '수업 시간에 토론할 여유는 없다'에 0~10 눈금으로 서 봅니다. 양 끝과 가운데에 선 분들의 까닭을 듣고 다시 서며, 토론이 '생각이 움직이는 경험'임을 몸으로 느낍니다.", techs: ["valuebar"] },
        { min: 15, title: "파노라마 토론 기법 안내", desc: "한 사건을 세 자리에서 나란히 보는 파노라마 토론의 원리와 3라운드(입장 말하기 → 서로 묻기 → 함께 살 길 찾기)를 안내합니다. 이기기보다 서로를 이해하는 토론이 교과 수업에서 어떻게 쓰이는지 사례로 봅니다.", techs: ["panorama"] },
        { min: 40, title: "파노라마 토론 실습", desc: "세 명씩 모둠을 지어 그림책 「완벽한 아이 팔아요」를 읽고, 부모·아이·마트의 자리를 하나씩 맡아 파노라마 토론을 직접 해 봅니다. 실습 학습지에 질문 만들기부터 라운드별 기록, 성찰까지 남깁니다.", book: "완벽한 아이 팔아요", worksheet: "panorama" },
        { min: 15, title: "토론 홈페이지 활용 안내", desc: "QR을 찍어 홈페이지에 들어가, '교과별 토론'에서 내 교과의 논제와 성취기준을 찾고 원하는 토론 기법으로 학습지를 바로 만들어 봅니다. 그림책 서재, 토론 기법, 자료실도 함께 둘러봅니다.", links: [{ label: "교과별 토론", go: "#subject-section", icon: "fa-chalkboard-user" }, { label: "학습지 만들기", go: "#worksheet-section", icon: "fa-file-pen" }, { label: "자료실", go: "#archive-section", icon: "fa-folder-open" }] }
    ]
};

function loadQrLib() {
    if (window.QRCode) return Promise.resolve(true);
    return new Promise(res => {
        const sc = document.createElement("script");
        sc.src = "https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js";
        sc.onload = () => res(!!window.QRCode);
        sc.onerror = () => res(false);
        document.head.appendChild(sc);
    });
}

function renderTrainingSection() {
    const box = document.getElementById("training-panel");
    if (!box) return;
    const total = TRAINING.flow.reduce((n, f) => n + f.min, 0);
    const techLink = (id) => {
        const t = techniques.find(x => x.id === id);
        return t ? `<button type="button" class="training-tech" onclick="openModal('tech','${id}')"><i class="fa-solid ${t.icon}"></i> ${t.name}</button>` : "";
    };
    const stepLinks = (f) => {
        const bi = f.book ? books.findIndex(b => b.title === f.book) : -1;
        const btns = [
            ...(f.techs || []).map(techLink),
            ...(f.links || []).map(l => `<button type="button" class="training-tech" onclick="document.querySelector('.nav-links a[href=\\'${l.go}\\']').click()"><i class="fa-solid ${l.icon}"></i> ${l.label}</button>`),
            bi >= 0 ? `<button type="button" class="training-tech" onclick="openModal('book', ${bi})"><i class="fa-solid fa-book"></i> 「${f.book}」</button>` : "",
            bi >= 0 && f.worksheet ? `<button type="button" class="training-tech" onclick="openBookWorksheet(${bi}, '${f.worksheet}')"><i class="fa-solid fa-file-pen"></i> 실습 학습지</button>` : ""
        ].filter(Boolean);
        return btns.length ? `<div class="training-techs no-print">${btns.join("")}</div>` : "";
    };
    const hm = (m) => m >= 60 ? `${Math.floor(m / 60)}시간${m % 60 ? " " + (m % 60) + "분" : ""}` : `${m}분`;
    box.innerHTML = `
        <div class="training-sheet">
            <div class="training-head">
                <span class="training-sub">${TRAINING.subtitle}</span>
                <h3>${TRAINING.title}</h3>
                ${TRAINING.tagline ? `<p class="training-tagline">${TRAINING.tagline}</p>` : ""}
            </div>
            <div class="training-body">
                <ol class="training-flow">
                    ${TRAINING.flow.map(f => `
                    <li>
                        <span class="training-min">${f.min}분</span>
                        <div>
                            <strong>${f.title}</strong>
                            <p>${f.desc}</p>
                            ${stepLinks(f)}
                        </div>
                    </li>`).join("")}
                </ol>
                <aside class="training-qr-box">
                    <div id="training-qr" class="training-qr" aria-label="사이트 주소 QR 코드"></div>
                    <p class="training-qr-cap">휴대폰 카메라로 찍으면<br><strong>교과별 토론</strong>으로 바로 들어갑니다</p>
                    <p class="training-url">${TRAINING.url.replace(/^https:\/\//, "").replace(/#.*$/, "")}</p>
                </aside>
            </div>
            <div class="training-memo">
                <h4><i class="fa-solid fa-people-group"></i> 내 수업에 가져갈 토론 한 장면</h4>
                <table>
                    <tr><th>교과 · 단원</th><td></td><th>논제</th><td></td></tr>
                    <tr><th>기법</th><td></td><th>넣을 자리</th><td>도입 · 전개 · 정리</td></tr>
                    <tr><th>수업 흐름</th><td colspan="3" class="training-memo-tall"></td></tr>
                    <tr><th>홈페이지에서<br>찾은 자료</th><td colspan="3" class="training-memo-mid"></td></tr>
                </table>
            </div>
            <p class="training-total">모두 ${total}분(${hm(total)}) · 시간이 모자라면 파노라마 실습의 3라운드를 짧게 하고, 남으면 홈페이지에서 학습지를 직접 만들어 보는 시간을 늘리세요.</p>
        </div>
        <div class="training-actions no-print">
            <button type="button" class="btn btn-primary" id="training-print"><i class="fa-solid fa-print"></i> 연수 안내 한 장 인쇄</button>
            <button type="button" class="btn btn-secondary" onclick="document.querySelector('.nav-links a[href=\\'#subject-section\\']').click()"><i class="fa-solid fa-chalkboard-user"></i> 교과별 토론 열기</button>
            <button type="button" class="btn btn-secondary" onclick="openQuickTechniques()"><i class="fa-solid fa-comments"></i> 토론 기법 모아 보기</button>
        </div>`;

    const qrBox = document.getElementById("training-qr");
    loadQrLib().then(ok => {
        if (!qrBox) return;
        if (!ok) { qrBox.innerHTML = `<p class="training-qr-fallback">QR을 불러오지 못했습니다.<br>아래 주소로 들어오세요.</p>`; return; }
        qrBox.innerHTML = "";
        new QRCode(qrBox, { text: TRAINING.url, width: 168, height: 168, correctLevel: QRCode.CorrectLevel.M });
    });
    const pb = document.getElementById("training-print");
    if (pb) pb.addEventListener("click", () => {
        document.body.classList.add("print-training");
        const done = () => { document.body.classList.remove("print-training"); window.removeEventListener("afterprint", done); };
        window.addEventListener("afterprint", done);
        window.print();
        setTimeout(done, 1500);
    });
}

// 스크롤에 따른 헤더 밀도 변화 (탭 전환과 충돌하지 않는 범위로 제한)
function initPolish() {
    const header = document.querySelector(".glass-header");
    if (!header) return;
    const onScroll = () => header.classList.toggle("scrolled", window.scrollY > 12);
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
}

// 모바일/태블릿 햄버거 메뉴 토글
function initMobileNav() {
    const toggle = document.getElementById("nav-toggle");
    const nav = document.getElementById("primary-nav");
    const backdrop = document.getElementById("nav-backdrop");
    if (!toggle || !nav) return;

    const setOpen = (open) => {
        nav.classList.toggle("open", open);
        if (backdrop) backdrop.classList.toggle("open", open);
        document.body.classList.toggle("nav-open", open);
        toggle.setAttribute("aria-expanded", open ? "true" : "false");
        toggle.setAttribute("aria-label", open ? "메뉴 닫기" : "메뉴 열기");
        toggle.innerHTML = open
            ? '<i class="fa-solid fa-xmark"></i>'
            : '<i class="fa-solid fa-bars"></i>';
    };

    toggle.addEventListener("click", () => setOpen(!nav.classList.contains("open")));
    if (backdrop) backdrop.addEventListener("click", () => setOpen(false));

    // 메뉴 항목 클릭 시 닫기
    nav.querySelectorAll("a").forEach((a) => a.addEventListener("click", () => setOpen(false)));

    // ESC 로 닫기
    document.addEventListener("keydown", (e) => {
        if (e.key === "Escape" && nav.classList.contains("open")) setOpen(false);
    });

    // 데스크톱 크기로 돌아가면 강제로 닫기(스크롤 잠금 해제)
    window.addEventListener("resize", () => {
        if (window.innerWidth > 1240 && nav.classList.contains("open")) setOpen(false);
    });
}

// 방문자 카운터 (abacus 공유 집계 API, 가입·키 불필요)
//  - 오늘의 방문자: 날짜별 키(visits-YYYY-MM-DD)로 매일 0부터 시작
//  - 누적 방문자: 고정 키(visits-total)로 계속 누적
//  - 같은 브라우저는 하루 1회만 두 카운터를 함께 +1
function initVisitorCounter() {
    const numEl = document.getElementById("vc-num");
    const totalEl = document.getElementById("vc-total");
    if (!numEl && !totalEl) return;

    const now = new Date();
    const dayKey = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}-${String(now.getDate()).padStart(2, "0")}`;
    const NS = "picturebc-debate";
    const API = "https://abacus.jasoncameron.dev";
    const visitedFlag = `pbc-visited-${dayKey}`;         // 이 브라우저가 오늘 이미 집계됐는지
    const alreadyVisited = localStorage.getItem(visitedFlag);

    // 처음 방문이면 hit(1 증가), 이미 방문했으면 get(증가 없이 읽기)
    const action = alreadyVisited ? "get" : "hit";
    const dayUrl = `${API}/${action}/${NS}/visits-${dayKey}`;
    const totalUrl = `${API}/${action}/${NS}/visits-total`;

    const animateTo = (el, target) => {
        if (!el) return;
        target = Math.max(1, parseInt(target, 10) || 1);
        const duration = 900;
        const start = performance.now();
        const step = (t) => {
            const p = Math.min(1, (t - start) / duration);
            const eased = 1 - Math.pow(1 - p, 3);
            el.textContent = Math.round(eased * target).toLocaleString();
            if (p < 1) {
                requestAnimationFrame(step);
            } else {
                el.textContent = target.toLocaleString();
                el.classList.add("vc-updated");
            }
        };
        requestAnimationFrame(step);
        // 배경 탭 등 rAF가 멈춘 환경에서도 최종 값이 표시되도록 안전장치
        setTimeout(() => { el.textContent = target.toLocaleString(); }, duration + 150);
    };

    // 마지막으로 확인된 서버 값을 저장해 두었다가, 통신이 실패하면 그 값을 보여준다.
    // (예전에는 실패 시 브라우저별 로컬 카운트를 써서 숫자가 1로 떨어져 '초기화'처럼 보였음)
    const lastKey = (name) => `pbc-last:${name}`;

    const loadCounter = (el, url, name) => {
        if (!el) return;
        const cached = parseInt(localStorage.getItem(lastKey(name)) || "0", 10);
        if (cached > 0) el.textContent = cached.toLocaleString();   // 응답 전까지 마지막 값 표시

        // get으로 읽었는데 서버에 키가 없으면(그날 첫 집계가 통신 오류로 실패한 경우 등)
        // hit으로 한 번 더 시도해 키를 만들고 집계한다. 그대로 두면 하루 종일 "–"로 남는다.
        const request = (u, isRetry) => fetch(u)
            .then((r) => (r.ok ? r.json() : Promise.reject(new Error("HTTP " + r.status))))
            .then((data) => {
                const v = Number(data && data.value);
                if (!Number.isFinite(v)) throw new Error("invalid response");
                localStorage.setItem(lastKey(name), String(v));
                localStorage.setItem(visitedFlag, "1");   // 집계에 실제로 성공했을 때만 기록
                animateTo(el, Math.max(v, cached));   // 카운터는 줄지 않으므로 뒤로 가지 않게
            })
            .catch(() => {
                if (!isRetry && u.indexOf("/get/") !== -1) return request(u.replace("/get/", "/hit/"), true);
                // 서버가 잠시 불안정해도 마지막으로 확인된 값을 유지 (초기화처럼 보이지 않게)
                if (cached > 0) animateTo(el, cached);
                else el.textContent = "–";
            });
        request(url, false);
    };

    loadCounter(numEl, dayUrl, `visits-${dayKey}`);
    loadCounter(totalEl, totalUrl, "visits-total");

    // '오늘 집계됨' 표시는 loadCounter에서 요청이 성공했을 때만 남긴다.
    // (예전에는 요청을 보내자마자 표시해, 통신이 실패하면 그날 내내 "–"로 남았음)
}

function initThemeToggle() {
    const themeToggle = document.getElementById("theme-toggle");
    if (!themeToggle) return;
    
    themeToggle.addEventListener("click", () => {
        const isDark = document.body.classList.contains("dark-mode");
        if (isDark) {
            document.body.classList.remove("dark-mode");
            document.body.classList.add("light-mode");
            themeToggle.innerHTML = '<i class="fa-solid fa-moon"></i>';
            localStorage.setItem("theme", "light");
        } else {
            document.body.classList.remove("light-mode");
            document.body.classList.add("dark-mode");
            themeToggle.innerHTML = '<i class="fa-solid fa-sun"></i>';
            localStorage.setItem("theme", "dark");
        }
    });
    
    // Load saved theme preference
    const savedTheme = localStorage.getItem("theme");
    if (savedTheme === "dark") {
        document.body.classList.remove("light-mode");
        document.body.classList.add("dark-mode");
        themeToggle.innerHTML = '<i class="fa-solid fa-sun"></i>';
    } else {
        document.body.classList.remove("dark-mode");
        document.body.classList.add("light-mode");
        themeToggle.innerHTML = '<i class="fa-solid fa-moon"></i>';
    }
}

function renderHeroBookshelf() {
    const shelf = document.getElementById("hero-bookshelf");
    if (!shelf || typeof books === 'undefined' || books.length === 0) return;
    
    // 12 representative books with diverse gradient themes (sorted indices)
    const selectedIndices = [0, 1, 2, 4, 6, 12, 22, 23, 30, 32, 38, 52];
    
    let html = "";
    
    // Row 1
    html += '<div class="shelf-row">';
    for (let i = 0; i < 6; i++) {
        const idx = selectedIndices[i];
        if (idx === undefined || !books[idx]) continue;
        const book = books[idx];
        const isRotated = (i % 3 === 0) ? "skewed-left" : (i % 5 === 0 ? "skewed-right" : "");
        html += `
            <div class="book-spine-3d ${isRotated}" style="background: ${book.gradient || 'var(--accent-coral)'}" onclick="openModal('book', ${idx})" title="${book.title} (클릭 시 토론 가이드 열기)">
                <div class="spine-text">${book.title}</div>
                <div class="spine-decor"></div>
            </div>
        `;
    }
    html += '</div><div class="shelf-board"></div>';
    
    // Row 2
    html += '<div class="shelf-row">';
    for (let i = 6; i < 12; i++) {
        const idx = selectedIndices[i];
        if (idx === undefined || !books[idx]) continue;
        const book = books[idx];
        const isRotated = (i % 3 === 0) ? "skewed-left" : (i % 4 === 0 ? "skewed-right" : "");
        html += `
            <div class="book-spine-3d ${isRotated}" style="background: ${book.gradient || 'var(--accent-coral)'}" onclick="openModal('book', ${idx})" title="${book.title} (클릭 시 토론 가이드 열기)">
                <div class="spine-text">${book.title}</div>
                <div class="spine-decor"></div>
            </div>
        `;
    }
    html += '</div><div class="shelf-board"></div>';
    
    shelf.innerHTML = html;
}

function initTabNavigation() {
    const navLinks = document.querySelectorAll('.nav-links a[href^="#"]');
    const sections = document.querySelectorAll('section[id$="-section"]');

    navLinks.forEach(link => {
        link.addEventListener('click', (e) => {
            e.preventDefault();
            const targetId = link.getAttribute('href').substring(1);
            
            navLinks.forEach(n => n.classList.remove('active'));
            link.classList.add('active');
            
            sections.forEach(s => {
                if(s.id === targetId || (targetId === 'search-section' && s.classList.contains('hero-section'))) {
                    s.classList.add('active');
                    s.style.display = 'block';
                } else if(s.id === targetId) {
                     s.style.display = 'block';
                } else {
                    s.classList.remove('active');
                    s.style.display = 'none';
                }
            });
            // Also hero section handling
            const hero = document.querySelector('.hero-section');
            if(hero) {
                if(targetId === 'search-section') {
                    hero.style.display = 'block';
                } else {
                    hero.style.display = 'none';
                }
            }
            
            window.scrollTo({top:0, behavior:'smooth'});
        });
    });
    
    // 왼쪽 위 이름(로고)을 누르면 메인 화면으로
    const logo = document.querySelector('.glass-header .logo');
    if (logo) logo.addEventListener('click', (e) => {
        e.preventDefault();
        const home = document.querySelector('.nav-links a[href="#search-section"]');
        if (home) home.click();
    });

    // Default Tab
    const hash = window.location.hash || '#search-section';
    const defaultLink = document.querySelector(`.nav-links a[href="${hash}"]`);
    if(defaultLink) {
        defaultLink.click();
    } else {
        // Fallback
        if(navLinks.length > 0) navLinks[0].click();
    }
}

// index.html 이 app.js 를 부를 때 붙이는 ?v= 값을 그대로 쓴다.
// 그림 파일 이름을 그대로 두고 내용만 바꿔도 새로 받아 가게 하려는 것이다.
const ASSET_VERSION = (function () {
    try {
        const src = (document.currentScript && document.currentScript.src) || "";
        const m = src.match(/[?&]v=([\d.]+)/);
        if (m) return m[1];
    } catch (e) {}
    return "5.6.2";
})();

function fetchRealCover(bookTitle, domElement) {
    const book = typeof books !== 'undefined' ? books.find(b => {
        const t1 = b.title.replace(/\s/g, '').toLowerCase();
        const t2 = bookTitle.replace(/\s/g, '').toLowerCase();
        const normalize = (str) => str.replace(/x/g, '엑스').replace(/X/g, '엑스');
        return normalize(t1) === normalize(t2) || t1.includes(t2) || t2.includes(t1);
    }) : null;

    if (book) {
        // Ensure absolute positioning context if needed
        if (window.getComputedStyle(domElement).position === 'static') {
            domElement.style.position = 'relative';
        }
        
        let fallbackCont = domElement.querySelector(".book-fallback-content");
        if (!fallbackCont) {
            fallbackCont = document.createElement("div");
            fallbackCont.className = "book-fallback-content";
            fallbackCont.style.cssText = "width:100%; height:100%; display:flex; flex-direction:column; justify-content:space-between; box-sizing:border-box; position:absolute; top:0; left:0; padding:12px;";
            
            // Move existing children to fallback container
            while (domElement.firstChild) {
                fallbackCont.appendChild(domElement.firstChild);
            }
            domElement.appendChild(fallbackCont);
        }
        
        let realImg = domElement.querySelector("img.real-book-cover-loaded");
        if (!realImg) {
            realImg = document.createElement("img");
            realImg.className = "real-book-cover-loaded";
            realImg.alt = `${bookTitle} 표지`;
            realImg.style.cssText = "width:100% !important; height:100% !important; object-fit:cover; border-radius:4px; display:none; border:none !important; outline:none !important; box-shadow:none !important; position:absolute; top:0; left:0;";
            domElement.appendChild(realImg);
        }
        
        realImg.onload = () => {
            realImg.style.display = "block";
            fallbackCont.style.display = "none";
            if (coverId === 14 || coverId === 44 || coverId === 46 || coverId === 21) {
                domElement.style.background = "#ffffff";
            }
        };
        realImg.onerror = () => {
            realImg.style.display = "none";
            fallbackCont.style.display = "flex";
        };
        
        const coverId = book.coverId;
        if (coverId === undefined || coverId === null) {   // 표지 이미지가 아직 없는 책
            realImg.style.display = "none";
            fallbackCont.style.display = "flex";
            return;
        }
        const ext = (coverId === 14 || coverId === 22 || coverId === 15 || coverId === 44 || coverId === 34) ? 'png' : 'jpg';
        if (coverId === 14 || coverId === 44 || coverId === 46 || coverId === 21) {
            realImg.style.objectFit = "contain";
        } else {
            realImg.style.objectFit = "cover";
        }
        const imgName = coverId === 44 ? `book_cover_${coverId}_v3` : `book_cover_${coverId}`;
        realImg.src = `images/${imgName}.${ext}?v=${ASSET_VERSION}`;
    }
}

function renderTechniques() {
    const container = document.getElementById("techniques-grid");
    if(!container) return;
    container.innerHTML = "";
    techniques.forEach(tech => {
        let booksText = "준비중";
        if(typeof books !== 'undefined') {
            const matchedBooks = books.filter(b => b.technique && b.technique.includes(tech.name.split(" ")[0]));
            if(matchedBooks.length > 0) {
                booksText = matchedBooks.map(b => b.title).join(", ");
            }
        }
        
        // 난이도 판별
        let difficulty = "초급";
        let difficultyClass = "badge-difficulty-low";
        let diffIcon = "fa-circle";
        
        const advancedTechs = ["lincoln", "leadership", "panel"];
        const intermediateTechs = ["procon", "socratic", "panorama", "digital", "reason"];
        
        if (advancedTechs.includes(tech.id)) {
            difficulty = "고급";
            difficultyClass = "badge-difficulty-high";
            diffIcon = "fa-circle-dot";
        } else if (intermediateTechs.includes(tech.id) || (tech.tags && tech.tags.includes("논리강화"))) {
            difficulty = "중급";
            difficultyClass = "badge-difficulty-mid";
            diffIcon = "fa-circle-half-stroke";
        }

        // 소요 시간 텍스트 정리
        let durationText = tech.time ? tech.time.split(" ")[0] : "40분";
        
        container.innerHTML += `
            <div class="technique-card" onclick="openModal('tech', '${tech.id}')" data-difficulty="${difficulty}" data-tags="${(tech.tags || []).join(",")}" data-name="${tech.name}" data-concept="${tech.concept}">
                <div class="tech-header">
                    <div class="tech-icon-wrapper">
                        <i class="fa-solid ${tech.icon}"></i>
                    </div>
                </div>
                <h3 style="margin-top:14px; font-size:1.15rem; color:var(--text-primary); font-family:var(--font-sans); font-weight:700;">${tech.name}</h3>
                <div class="tech-tags" style="margin-top:8px; display:flex; gap:6px; flex-wrap:wrap;">
                    ${(tech.tags || []).map(tag => `<span class="tech-tag">${tag}</span>`).join("")}
                </div>
                <p class="tech-desc">${tech.easy || tech.concept}</p>
                <div class="tech-footer" style="margin-top:auto; padding-top:14px; border-top:1px dashed var(--border-color); display:flex; justify-content:space-between; align-items:center;">
                    <span class="tech-matching-book" style="font-size:0.8rem; color:var(--text-secondary); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; max-width:180px;">
                        <i class="fa-solid fa-book" style="margin-right: 4px; color:var(--accent-coral);"></i> ${booksText}
                    </span>
                    <span class="tech-more-btn" style="font-size:0.85rem; font-weight:700; color:var(--accent-coral); white-space:nowrap;">
                        더보기 <i class="fa-solid fa-arrow-right"></i>
                    </span>
                </div>
            </div>
        `;
    });
}

function renderTheory() {
    const container = document.getElementById("theory-grid");
    if(!container || typeof debateTheory === 'undefined') return;
    container.innerHTML = "";
    debateTheory.sections.forEach(sec => {
        container.innerHTML += `
            <div class="theory-card">
                <div class="theory-icon-wrapper">
                    <i class="fa-solid ${sec.icon}"></i>
                </div>
                <h3>${sec.title}</h3>
                <p class="theory-content">${sec.content}</p>
                ${sec.keyPoints ? `
                    <ul class="theory-points">
                        ${sec.keyPoints.map(kp => `<li><strong>${kp.label}:</strong> ${kp.desc}</li>`).join("")}
                    </ul>
                ` : ''}
            </div>
        `;
    });
}

function renderBooks() {
    const container = document.getElementById("books-grid");
    if(!container || typeof books === 'undefined') return;
    container.innerHTML = "";
    books.forEach((book, idx) => {
        const card = document.createElement("div");
        card.className = "book-card";
        card.onclick = () => openModal('book', idx);
        
        const designInner = document.createElement("div");
        designInner.className = "book-design-inner";
        designInner.style.background = book.gradient || 'var(--accent-coral)';
        
        const titleSpan = document.createElement("span");
        titleSpan.className = "book-design-title";
        titleSpan.innerText = book.title;
        
        const iconI = document.createElement("i");
        iconI.className = `fa-solid ${book.icon || 'fa-book'} book-design-icon`;
        
        designInner.appendChild(titleSpan);
        designInner.appendChild(iconI);
        
        const infoDiv = document.createElement("div");
        infoDiv.className = "book-info";
        infoDiv.innerHTML = `
            <h4>${book.title}</h4>
            <p>${book.author}</p>
            <div style="margin-top:8px;">
                ${(book.tags || []).map(t => `<span class="tech-tag">${t}</span>`).join("")}
            </div>
        `;
        
        const bookDesign = document.createElement("div");
        bookDesign.className = "book-design";
        bookDesign.appendChild(designInner);
        
        card.appendChild(bookDesign);
        card.appendChild(infoDiv);
        container.appendChild(card);
        
        // Fetch real cover
        fetchRealCover(book.title, designInner);
    });
}

