const curAbbr = (code) => { const m = String(code).match(/^(.*?)-?\d{2}-\d{2}$/); return m ? m[1] : ""; };
const curCourse = (code) => CURRICULUM_COURSES[curAbbr(code)] || null;
const escAttr = (x) => String(x).replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
// 논제 카드에 붙는 '지금은'과 성취기준
function topicNowHTML(t) {
    return t.now ? `<p class="topic-now"><span class="topic-now-label">지금은</span>${t.now}</p>` : "";
}
function topicStdHTML(t, full) {
    const codes = (t.std || []).filter(c => CURRICULUM[c]);
    if (!codes.length) return "";
    if (full) return `<div class="topic-std-full"><strong><i class="fa-solid fa-book-bookmark"></i> 관련 성취기준 (2022 개정)</strong><ul>${codes.map(c => `<li><code>[${c}]</code> <em>${(curCourse(c) || [""])[0]}</em> ${CURRICULUM[c]}</li>`).join("")}</ul></div>`;
    return `<p class="topic-std"><i class="fa-solid fa-book-bookmark"></i> ${codes.map(c => `<span title="${escAttr((curCourse(c) || [""])[0] + " · " + CURRICULUM[c])}">[${c}] ${(curCourse(c) || [""])[0]}</span>`).join("")}</p>`;
}

