    "감정": { src: "kdca", label: "청소년건강행태조사 – 스트레스 인지율과 우울감 경험률" },
    "건강": { src: "kdca", label: "청소년건강행태조사 – 식습관·신체활동·수면" },
    "공동체": { src: "kosis", label: "사회조사 – 사회적 관계망과 자원봉사·기부 참여", q: "사회조사 자원봉사 기부" },
    "관계": { src: "kosis", label: "사회조사 – 사회적 관계망과 외로움", q: "사회적 관계망 외로움" },
